@startuml

class Department {}

class Room {}

class Bed {
  + Category : StayCategory
}

class StayCategory {
  + Price : double
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + Name : string
  + RegistrationDate : date
}

class Registration {
  + BasicIdentificationData : string
}

class Assessment {
  + Needs : string
  + ValidatedType : StayType
}

class WaitingListPosition {
  + Position : int
}

class Proposal {
  + Date : date
  + Status : string
}

class Stay {
  + StartDate : date
  + Status : string
  + IsDiscounted : boolean
}

class Invoice {
  + Amount : double
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

class Payment {
  + Amount : double
  + Date : date
}

Department "1" *-- "*" Room
Room "1" *-- "*" Bed
Bed "1" -- "1" StayCategory
Inhabitant "1" -- "*" Registration
Inhabitant "1" -- "*" Assessment
Inhabitant "1" -- "*" Stay
Inhabitant "1" -- "*" WaitingListPosition
StayType "1" -- "*" WaitingListPosition
StayType "1" -- "*" Proposal
Stay "1" -- "0..*" Invoice
Stay "1" -- "0..*" Payment
Invoice "1" -- "0..*" Payment
Invoice "1" -- "0..1" CreditNote

@enduml

